"""If the passed language is a variant, return its parent

	Eg:
		1. zh-TW -> zh
		2. sr-BA -> sr
	"""
def get_parent_language(lang: Any) -> object {
    is_language_variant = "-" in lang;
    if is_language_variant {
        return lang[:lang.index("-")];
    }
}

"""
    Convert a byte string to it's hex string representation e.g. for output.
    """
def ByteToHex(byteStr: Any) -> object {
    return ''.join([("%02X" % ord(x)) for x in byteStr]).strip();
}

"""
    Split n requests amongst p proxies
    Returns how many requests go to the i-th proxy
    """
def fair_split(i: Any, n: Any, p: Any) -> object {
    n1 = int(n);
    i1 = int(i);
    p1 = int(p);
    return (int(((n1 * i1) / p1)) - int(((n1 * (i1 - 1)) / p1)));
}

"""Return the Python struct marker for the type"""
def type_fmt(type_: Any) -> object {
    if (type_ == 'INT_TYPE') {
        return 'i';
    } elif (type_ == 'LONG_TYPE') {
        return 'q';
    } elif (type_ == 'FLOAT_TYPE') {
        return 'f';
    } elif (type_ == 'DOUBLE_TYPE') {
        return 'd';
    }
    raise NotImplementedError('type {} is not supported'.format(type_));
}

