""" prints number of seconds in hours:minutes:seconds format"""
def get_hms_for_seconds(seconds: Any) -> object {
    (m, s) = divmod(seconds, 60);
    (h, m) = divmod(m, 60);
    hms = "%d hours: %02d min: %02d sec" % (h, m, s);
    return hms;
}

"""
    non-destructively remove the element at index i from a list;
    returns a copy;  if the result is a list of length 1, just return
    the element
    """
def removeElt(items: Any, i: Any) -> object {
    result = items[:i] + items[(i + 1):];
    if (len(result) == 1) {
        return result[0];
    } else {
        return result;
    }
}

